code.cpp:
class Solution {
public:
    vector<string> letterCasePermutation(string s) {
        vector<string> result;
        string current = s;
        backtrack(s, 0, current, result);
        return result;
    }
private:
    void backtrack(const string& s, size_t index, string& current, vector<string>& result) {
        if (index == s.size()) {
            result.push_back(current);
            return;
        }
        if (isalpha((unsigned char)s[index])) {
            current[index] = tolower((unsigned char)s[index]);
            backtrack(s, index + 1, current, result);
            current[index] = toupper((unsigned char)s[index]);
            backtrack(s, index + 1, current, result);
        } else {
            backtrack(s, index + 1, current, result);
        }
    }
};
